import json

class ImportProblem(Exception):
    def __init__(self, line):
        self.line = line
        super().__init__(f'invalid line {line}')

def _is_valid_count(value):
    # Integer only: bool is a subclass of int and is invalid, and JSON
    # floats (integral or fractional) parse to float and are invalid.
    # Strings, null, and missing values are invalid too.
    return isinstance(value, int) and not isinstance(value, bool)

def _parse_line(raw):
    # Return the validated record for one nonblank physical line, or raise
    # ValueError for malformed UTF-8, malformed JSON, or invalid fields.
    text = raw.decode('utf-8')  # UnicodeDecodeError is a ValueError
    record = json.loads(text)   # JSONDecodeError is a ValueError
    if not isinstance(record, dict):
        raise ValueError()
    record_id = record.get('id')
    if not isinstance(record_id, str) or not record_id:
        raise ValueError()
    if not _is_valid_count(record.get('count')):
        raise ValueError()
    return record

def import_bytes(payload, store):
    # Phase 1: parse and validate every line without touching the store, so
    # a failure on any line leaves the store exactly unchanged.
    # Phase 2: only once the whole payload is valid, append in order.
    records = []
    for line, raw in enumerate(payload.splitlines(), 1):
        if not raw.strip():
            continue
        try:
            records.append(_parse_line(raw))
        except ValueError:
            raise ImportProblem(line)
    for record in records:
        store.append(record)
    return len(records)

